const MODEL={"type":"sequence","participants":[{"id":"GuestApp","label":"GuestApp"},{"id":"BookingApi","label":"BookingApi"},{"id":"PaymentProvider","label":"PaymentProvider"},{"id":"PartnerHub","label":"PartnerHub"}],"messages":[{"from":"GuestApp","to":"BookingApi","arrow":"request","label":"Post the booking"},{"from":"BookingApi","to":"BookingApi","arrow":"request","label":"Hold the room"},{"from":"BookingApi","to":"PaymentProvider","arrow":"request","label":"Authorise card","accent":true},{"from":"PaymentProvider","to":"BookingApi","arrow":"reply","label":"Authorised"},{"from":"BookingApi","to":"BookingApi","arrow":"request","label":"Confirm the hold"},{"from":"BookingApi","to":"PartnerHub","arrow":"request","label":"Tell the partner hub"},{"from":"BookingApi","to":"GuestApp","arrow":"reply","label":"201 Created"}],"expect":{"nodes":4,"connectors":7},"title":"1. Checkout payment, card authorised","subtitle":"The calls a Roamstay checkout makes in order when the card is authorised, for the product and engineering team","source":"Source: the payments brief, as summarised in the request. Left out: the declined card, drawn on board 2."};
const THEME={};
const SWATCH={
white:['#FFFFFF','#B3B3B3','#1E1E1E'],black:['#1E1E1E','#B3B3B3','#FFFFFF'],
