const t=text(key,label,REGULAR,TYPE.label,kx,ky+18);
made.push(t);
if(t.x+t.width>keyWidth-32&&x0>32){
made.forEach((n)=>{n.x+=32-x0;n.y+=72;});
ky+=72;
}
kr=Math.max(kr,t.x+t.width);
kx=up8(t.x+t.width+48);
