parent.appendChild(sec);
sec.name=label;
sec.x=x;
sec.y=y;
sec.resize(w,hh);
sec.fills=solid(TINT[tint]||TINT.gray);
created.push(sec.id);
text(sec,label,SEMI,TYPE.zone,32,32);
