});
M.messages.forEach((m,k)=>{
const yy=oy+rows[k];
const a=index.get(m.from),b=index.get(m.to);
const style={...(ARROWS[m.arrow]||ARROWS.request),...(m.accent?{color:ACCENT,weight:T.accent.message}:{})};
