line:'STRAIGHT',m0:'POINT',m1:'POINT',label,dashed:style.dashed,endCap:'NONE',color:style.color,weight:style.weight});
let from=start;
if(self){
const p1=anchor(board,x+selfReach(m),yy,`at:${k}:out`);
