boardId:board.id,
tag:tagged?{namespace:TAG,key:MODEL.title}:null,
bounds:{x:board.x,y:board.y,w:board.width,h:board.height},
counts,
expect,
elements,
links,
warnings,
createdCount:created.length,
};

