s.resize(w,hh);
parent.appendChild(s);
s.x=x;
s.y=y;
created.push(s.id);
return s;
}
function marker(parent,digit,x,y,name){
const p=shape(parent,'initial',digit,x,y,32,32,name,TYPE.small);
const m=SWATCH[T.role.marker];
p.fills=solid(m[0]);
p.strokes=solid(m[1]);
p.text.fills=solid(m[2]);
