}
function anchor(parent,cx,cy,name){
const a=figma.createShapeWithText();
a.shapeType='ELLIPSE';
a.name=name;
a.fills=[];
a.strokes=[];
a.resize(16,16);
parent.appendChild(a);
a.x=cx-8;
a.y=cy-8;
created.push(a.id);
